import re
p='src/dates.js'; s=open(p).read()
s=s.replace('''export function addMonths(date, months) {
  const next = new Date(date.getTime());
  next.setUTCMonth(next.getUTCMonth() + months);
  return next;
}''','''// Adds calendar months, clamping to the last day of the target month when it
// is shorter (e.g. 2024-01-31 + 1 month = 2024-02-29).
export function addMonths(date, months) {
  const total = date.getUTCMonth() + months;
  const year = date.getUTCFullYear() + Math.floor(total / 12);
  const month = ((total % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  return new Date(Date.UTC(year, month, Math.min(date.getUTCDate(), lastDay)));
}''')
open(p,'w').write(s)
p='src/schedule.js'; s=open(p).read()
s=s.replace('''// The next `count` renewal dates for a subscription that started on `start`.''','''// The next `count` renewal dates for a subscription that started on `start`.
// Each date is measured from `start`, not from the previous renewal, so a
// clamped short month (31 Jan -> 29 Feb) doesn't shift later renewals.''')
s=s.replace('''  let current = start;
  for (let i = 0; i < count; i++) {
    current = addMonths(current, step);
    dates.push(current);
  }''','''  for (let i = 1; i <= count; i++) {
    dates.push(addMonths(start, step * i));
  }''')
open(p,'w').write(s)
EOF
cat >> test/schedule.test.js <<'EOF'

test("monthly renewals clamp to the last day of short months without drifting", () => {
  assert.deepEqual(dates("2024-01-31", "monthly", 4), ["2024-02-29", "2024-03-31", "2024-04-30", "2024-05-31"]);
  assert.deepEqual(dates("2023-01-31", "monthly", 2), ["2023-02-28", "2023-03-31"]);
});

test("annual renewals from a leap day fall on 28 February, then return to the 29th", () => {
  assert.deepEqual(dates("2024-02-29", "annual", 4), ["2025-02-28", "2026-02-28", "2027-02-28", "2028-02-29"]);
});

test("monthly renewals cross year boundaries", () => {
  assert.deepEqual(dates("2024-11-30", "monthly", 3), ["2024-12-30", "2025-01-30", "2025-02-28"]);
});
EOF
cat >> test/invoices.test.js <<'EOF'

test("invoices for a month-end start fall on the last day of short months", () => {
  const lines = upcomingInvoices({ start: "2024-01-31", plan: "monthly", tier: "pro" }, 3);
  assert.deepEqual(lines.map((l) => l.date), ["2024-02-29", "2024-03-31", "2024-04-30"]);
});
EOF
npm test 2>&1 | tail -12; git diff --stat

